public void TryAttach_ValidHeaderV0_ParsesVersionAndLength()
{
    var image = BuildTapImage(version: 0, pulseData: new byte[0x10]);

    var ok = TapImage.TryAttach(image, out var tap);

    ok.Should().BeTrue();
    tap.Should().NotBeNull();
    tap!.Version.Should().Be(0);
    tap.PulseDataLength.Should().Be(0x10);
}

/// <summary>
/// FR/TR: FR-TAPE
/// Use case: A buffer whose first 12 bytes are not the canonical
/// "C64-TAPE-RAW" signature must be rejected so the datasette never
/// pretends to play random bytes.
/// Acceptance: TryAttach returns false; out image is null.
/// </summary>
[Fact]

public void TryAttach_BadSignature_ReturnsFalse()
{
    var bytes = new byte[24];
    // Wrong signature: "BAD-SIGNATURE" prefix
    var bad = "BAD-SIGNATUR"u8;
    bad.CopyTo(bytes.AsSpan(0, 12));
    // Plausible version + size to prove rejection is signature-driven.
    bytes[12] = 0;
    bytes[16] = 4;

    var ok = TapImage.TryAttach(bytes, out var tap);

    ok.Should().BeFalse();
    tap.Should().BeNull();
}

/// <summary>
/// FR/TR: FR-TAPE
/// Use case: Pulse iteration for v0/v1 short-form bytes returns
/// byte * 8 host cycles per pulse, which matches VICE's TAP timing
/// convention used by RUNTIME-TAPE-001.
/// Acceptance: For pulse data [0x08, 0x10, 0x20], reader yields 64,
/// 128, 256 cycles, then reports no more pulses.
/// </summary>
[Fact]

public void PulseReader_ShortFormBytes_YieldsByteTimesEight()
{
    var image = BuildTapImage(version: 0, pulseData: new byte[] { 0x08, 0x10, 0x20 });
    TapImage.TryAttach(image, out var tap).Should().BeTrue();

    var reader = tap!.CreatePulseReader();

    reader.TryReadNextPulse(out var p1).Should().BeTrue();
    p1.Should().Be(64);
    reader.TryReadNextPulse(out var p2).Should().BeTrue();
    p2.Should().Be(128);
    reader.TryReadNextPulse(out var p3).Should().BeTrue();
    p3.Should().Be(256);
    reader.TryReadNextPulse(out _).Should().BeFalse();
}

/// <summary>
/// FR/TR: FR-TAPE
/// Use case: A datasette with a tape inserted but the motor or play
/// button disengaged must NOT emit pulses, mirroring physical motor
/// gating that the CIA1 timing depends on.
/// Acceptance: With MotorEnabled=false (default), TryReadNextPulse
/// returns false even though HasTape is true.
/// </summary>
[Fact]

public void Datasette_MotorOff_DoesNotEmitPulses()
{
    var datasette = new Datasette();
    datasette.InsertTape(BuildTapImage(version: 0, pulseData: new byte[] { 0x08, 0x10 }));
    datasette.PlayPressed = true;
    datasette.MotorEnabled = false;

    var emitted = datasette.TryReadNextPulse(out var cycles);

    emitted.Should().BeFalse();
    cycles.Should().Be(0);
    datasette.HasTape.Should().BeTrue();
}

/// <summary>
/// FR/TR: FR-TAPE
/// Use case: With motor on and play pressed, the datasette streams
/// pulses from the inserted tape image into the cycle-budget domain
/// (consumed by the CIA1 FLAG line and KERNAL tape routines).
/// Acceptance: TryReadNextPulse returns true and yields byte * 8
/// cycles for the first pulse byte.
/// </summary>
[Fact]

public void Datasette_MotorOnAndPlay_EmitsPulses()
{
    var datasette = new Datasette();
    datasette.InsertTape(BuildTapImage(version: 0, pulseData: new byte[] { 0x08, 0x10 }));
    datasette.MotorEnabled = true;
    datasette.PlayPressed = true;

    var emitted = datasette.TryReadNextPulse(out var cycles);

    emitted.Should().BeTrue();
    cycles.Should().Be(64);
}

public void NoTape_TryReadNextPulse_ReturnsFalse_Regardless()
{
    var ds = new Datasette();
    ds.MotorEnabled = true;
    ds.PlayPressed = true;

    for (var i = 0; i < MotorRampCycles + 1; i++)
        ds.Tick();

    Assert.False(ds.TryReadNextPulse(out _),
        "TryReadNextPulse must return false when no tape is inserted (VICE: reader is null).");
}

/// <summary>
/// TR-TAPE-EDGE-001 / RUNTIME-TAPE-002.
/// Use case: After setting MotorEnabled = true with a tape inserted and
/// PlayPressed = true, TryReadNextPulse must return false for at least
/// MinRampCycles (12,808) cycles - the ramp is still active.
/// Acceptance: After 12,808 Tick() calls, TryReadNextPulse still returns false.
/// VICE datasette.c:62 MOTOR_DELAY=32000 > 12808 so ramp is active at 12808.
/// </summary>
[Fact]

public void MotorOn_WithTape_PulseBlockedDuringRamp()
{
    var ds = new Datasette();
    ds.InsertTape(BuildMinimalTap());
    ds.MotorEnabled = true;
    ds.PlayPressed = true;

    for (var i = 0; i < MinRampCycles; i++)
        ds.Tick();

    Assert.False(ds.TryReadNextPulse(out _),
        $"TryReadNextPulse must return false during the motor ramp " +
        $"(first {MinRampCycles} cycles; VICE MOTOR_DELAY=32000 datasette.c:62).");
}

/// <summary>
/// TR-TAPE-EDGE-001 / RUNTIME-TAPE-002.
/// Use case: After the full 32,000-cycle motor ramp, TryReadNextPulse
/// must return true (the motor is at speed and the tape delivers pulses).
/// Acceptance: After MotorRampCycles Tick() calls, TryReadNextPulse returns true.
/// VICE datasette.c:62 MOTOR_DELAY=32000.
/// </summary>
[Fact]

public void MotorOn_WithTape_PulseAvailable_AfterFullRamp()
{
    var ds = new Datasette();
    ds.InsertTape(BuildMinimalTap());
    ds.MotorEnabled = true;
    ds.PlayPressed = true;

    for (var i = 0; i < MotorRampCycles; i++)
        ds.Tick();

    Assert.True(ds.TryReadNextPulse(out _),
        $"TryReadNextPulse must return true after the {MotorRampCycles}-cycle motor ramp " +
        "(VICE MOTOR_DELAY=32000 datasette.c:62).");
}

/// <summary>
/// TR-TAPE-EDGE-001 / RUNTIME-TAPE-002.
/// Use case: If MotorEnabled is set to false during or after the ramp,
/// the ramp counter resets. Setting motor off then on requires a full
/// new ramp before pulses are delivered.
/// Acceptance: After a complete ramp, motor off + motor on + 12,808 ticks,
/// TryReadNextPulse still returns false (ramp reset).
/// VICE datasette.c:1196 (motor stop: motor_stop_clk = MOTOR_DELAY).
/// </summary>
[Fact]

    public void MotorOff_ThenOn_ResetsRamp()
    {
        var ds = new Datasette();
        ds.InsertTape(BuildMinimalTap());
        ds.MotorEnabled = true;
        ds.PlayPressed = true;

        // Complete the ramp.
        for (var i = 0; i < MotorRampCycles; i++)
            ds.Tick();
        Assert.True(ds.TryReadNextPulse(out _), "Precondition: pulse available after ramp.");

        // Motor off resets ramp.
        ds.Rewind();
        ds.MotorEnabled = false;
        ds.Tick();
        ds.MotorEnabled = true;

        // First 12,808 cycles after motor re-enable: still in ramp.
        for (var i = 0; i < MinRampCycles; i++)
            ds.Tick();

        Assert.False(ds.TryReadNextPulse(out _),
            "Motor off then on must restart the ramp from zero " +
            "(VICE datasette.c motor_stop_clk reset on motor off).");
    }
}

public void SenseLine_True_WhenNoButtonPressed()
{
    var ds = new Datasette();
    ds.Reset();

    ds.SenseLine.Should().BeTrue(
        "SenseLine must be high (true) when PlayPressed = false " +
        "and RecordPressed = false (C64 CIA1 $DC01 bit 4 = 1; VICE datasette.c sense line).");
}

/// <summary>
/// TR-TAP-EDGE-001 / RUNTIME-TAPE-002.
/// Use case: SenseLine must be false (low) when PlayPressed is true.
/// This is the PLAY state; CIA1 $DC01 bit 4 reads as 0.
/// Acceptance: After PlayPressed = true, SenseLine = false.
/// VICE datasette.c: sense line goes low when PLAY is pressed.
/// </summary>
[Fact]

public void SenseLine_False_WhenPlayPressed()
{
    var ds = new Datasette();
    ds.Reset();
    ds.PlayPressed = true;

    ds.SenseLine.Should().BeFalse(
        "SenseLine must be low (false) when PlayPressed = true " +
        "(CIA1 $DC01 bit 4 = 0; VICE datasette.c sense line active-low).");
}

/// <summary>
/// TR-TAP-EDGE-001 / RUNTIME-TAPE-002.
/// Use case: SenseLine must be false (low) when RecordPressed is true.
/// RECORD also asserts the SENSE line (same physical signal as PLAY).
/// Acceptance: After RecordPressed = true, SenseLine = false.
/// VICE datasette.c: RECORD state asserts sense line just as PLAY does.
/// </summary>
[Fact]

public void SenseLine_ReturnsHigh_WhenPlayReleased()
{
    var ds = new Datasette();
    ds.Reset();
    ds.PlayPressed = true;
    ds.SenseLine.Should().BeFalse("precondition: play pressed.");

    ds.PlayPressed = false;

    ds.SenseLine.Should().BeTrue(
        "SenseLine must return high when Play is released " +
        "(CIA1 $DC01 bit 4 returns to 1).");
}

/// <summary>
/// TR-TAP-EDGE-001 / RUNTIME-TAPE-002.
/// Use case: TryWritePulse stores the cycle count when RecordPressed is true.
/// Record mode stores pulses to an internal buffer for later inspection
/// (models the Datasette write head writing to tape).
/// Acceptance: RecordPressed = true, TryWritePulse(128) returns true;
/// RecordedPulseCount increases by 1.
/// VICE datasette.c: record mode accumulates pulses to image buffer.
/// </summary>
[Fact]

public void SenseLine_False_WhenRecordPressed()
{
    var ds = new Datasette();
    ds.Reset();
    ds.RecordPressed = true;

    ds.SenseLine.Should().BeFalse(
        "SenseLine must be low (false) when RecordPressed = true " +
        "(CIA1 $DC01 bit 4 = 0; VICE datasette.c RECORD active-low sense).");
}

/// <summary>
/// TR-TAP-EDGE-001 / RUNTIME-TAPE-002.
/// Use case: SenseLine returns to true after Play is released.
/// Acceptance: PlayPressed = true -> false: SenseLine transitions false -> true.
/// </summary>
[Fact]

public void TryWritePulse_StorePulse_WhenRecordPressed()
{
    var ds = new Datasette();
    ds.Reset();
    ds.RecordPressed = true;
    ds.MotorEnabled = true;
    var countBefore = ds.RecordedPulseCount;

    var result = ds.TryWritePulse(128);

    result.Should().BeTrue("TryWritePulse must return true when RecordPressed and MotorEnabled.");
    ds.RecordedPulseCount.Should().Be(countBefore + 1,
        "RecordedPulseCount must increment after each successful TryWritePulse " +
        "(VICE datasette.c record buffer append).");
}

/// <summary>
/// TR-TAP-EDGE-001 / RUNTIME-TAPE-002.
/// Use case: TryWritePulse returns false when RecordPressed is false.
/// You cannot write to the tape without the record mode engaged.
/// Acceptance: RecordPressed = false, TryWritePulse returns false.
/// </summary>
[Fact]

public void TryWritePulse_ReturnsFalse_WhenNotRecording()
{
    var ds = new Datasette();
    ds.Reset();
    ds.RecordPressed = false;
    ds.MotorEnabled = true;

    var result = ds.TryWritePulse(128);

    result.Should().BeFalse(
        "TryWritePulse must return false when RecordPressed = false " +
        "(VICE datasette.c: write only active in record mode).");
}

/// <summary>
/// TR-TAP-EDGE-001 / RUNTIME-TAPE-002.
/// Use case: TryWritePulse returns false when motor is not enabled,
/// even if RecordPressed is true.
/// Acceptance: RecordPressed = true, MotorEnabled = false -> TryWritePulse returns false.
/// VICE datasette.c: motor must be running for any tape I/O.
/// </summary>
[Fact]

    public void TryWritePulse_ReturnsFalse_WhenMotorOff()
    {
        var ds = new Datasette();
        ds.Reset();
        ds.RecordPressed = true;
        ds.MotorEnabled = false;

        var result = ds.TryWritePulse(128);

        result.Should().BeFalse(
            "TryWritePulse must return false when motor is off " +
            "(VICE datasette.c: motor required for tape write).");
    }
}

public void Rewind_ReturnsToFirstPulse()
{
    var datasette = new Datasette();
    datasette.InsertTape(BuildTapImage(version: 0, pulseData: new byte[] { 0x08, 0x10, 0x20 }));
    datasette.MotorEnabled = true;
    datasette.PlayPressed = true;

    datasette.TryReadNextPulse(out _).Should().BeTrue();
    datasette.TryReadNextPulse(out _).Should().BeTrue();

    datasette.Rewind();

    var emitted = datasette.TryReadNextPulse(out var cycles);
    emitted.Should().BeTrue();
    cycles.Should().Be(64);
}

/// <summary>
/// FR/TR: FR-TAPE (BACKFILL-TAPE rewind + seek)
/// Use case: SeekTo(0) is the indexed form of Rewind(): both must
/// reposition the cursor at pulse 0 so callers can use either spelling.
/// Acceptance: Insert [0x08, 0x10, 0x20]. Read one pulse. SeekTo(0)
/// returns true. Next TryReadNextPulse returns cycles == 64.
/// </summary>
[Fact]

public void SeekTo_Zero_IsEquivalentToRewind()
{
    var datasette = new Datasette();
    datasette.InsertTape(BuildTapImage(version: 0, pulseData: new byte[] { 0x08, 0x10, 0x20 }));
    datasette.MotorEnabled = true;
    datasette.PlayPressed = true;

    datasette.TryReadNextPulse(out _).Should().BeTrue();

    var seekOk = datasette.SeekTo(0);
    seekOk.Should().BeTrue();

    var emitted = datasette.TryReadNextPulse(out var cycles);
    emitted.Should().BeTrue();
    cycles.Should().Be(64);
}

/// <summary>
/// FR/TR: FR-TAPE (BACKFILL-TAPE rewind + seek)
/// Use case: SeekTo(1) skips the first pulse so the next read returns
/// the second pulse, supporting fast-forward to a known offset.
/// Acceptance: Insert [0x08, 0x10, 0x20]. SeekTo(1) returns true. Next
/// TryReadNextPulse returns cycles == 128 (0x10 * 8).
/// </summary>
[Fact]

public void SeekTo_One_SkipsFirstPulse()
{
    var datasette = new Datasette();
    datasette.InsertTape(BuildTapImage(version: 0, pulseData: new byte[] { 0x08, 0x10, 0x20 }));
    datasette.MotorEnabled = true;
    datasette.PlayPressed = true;

    var seekOk = datasette.SeekTo(1);
    seekOk.Should().BeTrue();

    var emitted = datasette.TryReadNextPulse(out var cycles);
    emitted.Should().BeTrue();
    cycles.Should().Be(128);
}

/// <summary>
/// FR/TR: FR-TAPE (BACKFILL-TAPE rewind + seek)
/// Use case: SeekTo with an index beyond the tape's pulse count must
/// fail gracefully (return false) and leave the cursor unchanged so
/// callers can probe boundaries without crashing or losing position.
/// Acceptance: Insert 3-pulse tape. Read first pulse. SeekTo(100)
/// returns false. Next TryReadNextPulse returns the SECOND pulse
/// (cursor was not moved by the failed seek).
/// </summary>
[Fact]

public void SeekTo_OutOfRange_ReturnsFalseAndLeavesCursorUnchanged()
{
    var datasette = new Datasette();
    datasette.InsertTape(BuildTapImage(version: 0, pulseData: new byte[] { 0x08, 0x10, 0x20 }));
    datasette.MotorEnabled = true;
    datasette.PlayPressed = true;

    datasette.TryReadNextPulse(out var first).Should().BeTrue();
    first.Should().Be(64);

    var seekOk = datasette.SeekTo(100);
    seekOk.Should().BeFalse();

    var emitted = datasette.TryReadNextPulse(out var cycles);
    emitted.Should().BeTrue();
    cycles.Should().Be(128);
}

/// <summary>
/// FR/TR: FR-TAPE (BACKFILL-TAPE rewind + seek)
/// Use case: Calling Rewind() on a datasette with no tape inserted
/// must be a safe no-op so callers do not have to guard with HasTape.
/// Acceptance: New Datasette (no tape). Rewind() does not throw.
/// SeekTo(0) returns false. HasTape remains false.
/// </summary>
[Fact]

public void Rewind_NoTape_IsNoOp()
{
    var datasette = new Datasette();

    var rewind = () => datasette.Rewind();
    rewind.Should().NotThrow();

    datasette.SeekTo(0).Should().BeFalse();
    datasette.HasTape.Should().BeFalse();
}

public void NoTape_FlagNeverTriggers()
{
    var (cia, irq, _) = BuildCia1();
    var datasette = new Datasette();
    datasette.MotorEnabled = true;
    datasette.PlayPressed = true;
    var binding = new DatasetteCia1FlagBinding(datasette, cia);

    cia.Write(0xDC0D, 0x90);

    for (var i = 0; i < 100_000; i++)
        binding.Tick();

    var icr = cia.Read(0xDC0D);
    (icr & 0x10).Should().Be(0x00, "no tape inserted means no pulses to latch FLAG");
    irq.IsAsserted.Should().BeFalse("FLAG never fires so IRQ stays low");
}

/// <summary>
/// FR/TR: FR-TAPE + FR-CIA (BACKFILL-TAPE Datasette CIA1 FLAG).
/// Use case: A datasette with a tape but motor off (or play not
/// pressed) must not emit pulses, so the CIA1 FLAG line stays
/// quiet. This mirrors the physical motor + play gating the
/// KERNAL relies on for tape control.
/// Acceptance: After 100_000 binding ticks with MotorEnabled=false,
/// CIA1 ICR bit 4 stays clear.
/// </summary>
[Fact]

public void TapeInsertedButMotorOff_FlagNeverTriggers()
{
    var (cia, irq, _) = BuildCia1();
    var datasette = new Datasette();
    datasette.InsertTape(BuildTapImage(version: 0, pulseData: new byte[] { 0x04, 0x04, 0x04 }));
    datasette.MotorEnabled = false;
    datasette.PlayPressed = true;
    var binding = new DatasetteCia1FlagBinding(datasette, cia);

    cia.Write(0xDC0D, 0x90);

    for (var i = 0; i < 100_000; i++)
        binding.Tick();

    var icr = cia.Read(0xDC0D);
    (icr & 0x10).Should().Be(0x00, "motor off means no pulses reach FLAG");
    irq.IsAsserted.Should().BeFalse("FLAG never fires so IRQ stays low");
}

/// <summary>
/// FR/TR: FR-TAPE + FR-CIA (BACKFILL-TAPE Datasette CIA1 FLAG).
/// Use case: With motor + play on, the binding pulls each pulse
/// from the tape after its cycle interval elapses and triggers
/// CIA1 FLAG. Software polls ICR (destructive read clears the
/// latch); the next pulse re-latches. Three pulses in a row are
/// observed independently.
/// Acceptance: For pulse data [0x04, 0x08, 0x10] (32, 64, 128
/// cycles), three FLAG latches are observed sequentially after
/// the binding accumulates each pulse's cycle budget.
/// </summary>
[Fact]

public void MotorOnPlayPressed_FlagFiresPerPulse()
{
    var (cia, _, _) = BuildCia1();
    var datasette = new Datasette();
    // Three short pulses: 4 * 8 = 32 cycles, 8 * 8 = 64, 16 * 8 = 128.
    datasette.InsertTape(BuildTapImage(version: 0, pulseData: new byte[] { 0x04, 0x08, 0x10 }));
    datasette.MotorEnabled = true;
    datasette.PlayPressed = true;
    var binding = new DatasetteCia1FlagBinding(datasette, cia);

    // Pulse 1: 32 cycles.
    for (var i = 0; i < 32; i++)
        binding.Tick();
    var icr1 = cia.Read(0xDC0D);
    (icr1 & 0x10).Should().Be(0x10, "first pulse latches FLAG after its cycle budget elapses");
    (cia.Read(0xDC0D) & 0x10).Should().Be(0x00, "ICR read clears the FLG latch");

    // Pulse 2: another 64 cycles.
    for (var i = 0; i < 64; i++)
        binding.Tick();
    var icr2 = cia.Read(0xDC0D);
    (icr2 & 0x10).Should().Be(0x10, "second pulse re-latches FLAG");
    (cia.Read(0xDC0D) & 0x10).Should().Be(0x00, "ICR read clears the FLG latch again");

    // Pulse 3: another 128 cycles.
    for (var i = 0; i < 128; i++)
        binding.Tick();
    var icr3 = cia.Read(0xDC0D);
    (icr3 & 0x10).Should().Be(0x10, "third pulse re-latches FLAG");
}

/// <summary>
/// FR/TR: FR-TAPE + FR-CIA (BACKFILL-TAPE Datasette CIA1 FLAG).
/// Use case: When the host has enabled FLG in CIA1's IMR (bit 4),
/// the FLAG transition from a tape pulse must drive the CIA1 IRQ
/// output - this is how the KERNAL's tape ISR gets called. Without
/// the IMR enable, the latch still happens (polled mode) but no
/// IRQ fires.
/// Acceptance: After enabling IMR bit 4 ($90 to $DC0D), ticking
/// the binding long enough to consume the first pulse drives the
/// IRQ line asserted. The ICR read returns $90 (IR master + FLG).
/// </summary>
[Fact]

    public void MotorOnPlayPressed_WithImrEnabled_AssertsIrq()
    {
        var (cia, irq, _) = BuildCia1();
        var datasette = new Datasette();
        datasette.InsertTape(BuildTapImage(version: 0, pulseData: new byte[] { 0x04, 0x08 }));
        datasette.MotorEnabled = true;
        datasette.PlayPressed = true;
        var binding = new DatasetteCia1FlagBinding(datasette, cia);

        cia.Write(0xDC0D, 0x90);

        // 32 cycles consumes the first pulse (4 * 8).
        for (var i = 0; i < 32; i++)
            binding.Tick();

        irq.IsAsserted.Should().BeTrue("with IMR bit 4 enabled, pulse-driven FLAG must assert IRQ");
        cia.Read(0xDC0D).Should().Be(0x90, "ICR returns IR master bit plus FLG bit");
    }
}

public void DefaultC64Build_RegistersDatasetteAndCia1FlagBinding()
{
    var machine = TryBuildC64Machine();
    Assert.SkipWhen(machine is null, "C64 ROM set is not available in this environment; integration assertions require BASIC/KERNAL/character ROMs.");

    machine.Devices.All.OfType<ITapeDevice>().Should().HaveCount(1,
        "C64 with TapePortConnected exposes a Datasette");
    machine.Devices.All.OfType<DatasetteCia1FlagBinding>().Should().HaveCount(1,
        "the builder must instantiate the Datasette to CIA1 FLAG binding alongside the Datasette");
}

/// <summary>
/// FR/TR: FR-TAPE + FR-CIA (BACKFILL-TAPE builder integration).
/// Use case: With a tape inserted, motor on, and play pressed, the
/// system clock ticking the binding must deliver each tape pulse
/// through to CIA1's FLAG latch (ICR bit 4) without any extra
/// caller-side plumbing.
/// Acceptance: After loading a TAP image with a 4*8=32-cycle first
/// pulse and stepping the C64 clock for at least 32 cycles, CIA1
/// ICR reports bit 4 set.
/// </summary>
[Fact]

public void BuiltC64_WithTape_DeliversPulseToCia1Flag()
{
    var machine = TryBuildC64Machine();
    Assert.SkipWhen(machine is null, "C64 ROM set is not available in this environment; integration assertions require BASIC/KERNAL/character ROMs.");
    var datasette = machine.Devices.All.OfType<Datasette>().Single();
    var cia1 = machine.Devices.GetByRole(DeviceRole.Cia1) as Mos6526
        ?? throw new InvalidOperationException("Built C64 did not expose CIA1.");

    // Single 32-cycle pulse (4 * 8 = 32 cycles).
    datasette.InsertTape(BuildTapImage(version: 0, pulseData: new byte[] { 0x04 }));
    datasette.MotorEnabled = true;
    datasette.PlayPressed = true;

    // Step the clock long enough for the binding to consume the pulse.
    // The binding is Phi2 + divisor 1 so each Step() fires one binding tick.
    machine.Clock.Step(64);

    var icr = cia1.Read(0xDC0D);
    (icr & 0x10).Should().Be(0x10,
        "with motor+play and a tape inserted, the binding ticked by the system clock latches CIA1 FLAG");
}

/// <summary>
/// FR/TR: FR-TAPE + FR-CIA (BACKFILL-TAPE builder integration).
/// Use case: When no tape is inserted into the built machine, the
/// system clock can still tick the binding indefinitely without
/// ever asserting CIA1 FLAG. This isolates the tape path so non
/// tape software is never disturbed.
/// Acceptance: After 10_000 Step()s with no tape inserted, CIA1
/// ICR bit 4 stays clear.
/// </summary>
[Fact]

    public void BuiltC64_WithoutTape_NeverLatchesCia1Flag()
    {
        var machine = TryBuildC64Machine();
        Assert.SkipWhen(machine is null, "C64 ROM set is not available in this environment; integration assertions require BASIC/KERNAL/character ROMs.");
        var datasette = machine.Devices.All.OfType<Datasette>().Single();
        var cia1 = machine.Devices.GetByRole(DeviceRole.Cia1) as Mos6526
            ?? throw new InvalidOperationException("Built C64 did not expose CIA1.");

        // No tape inserted; even with motor/play asserted the gate inside
        // Datasette.TryReadNextPulse returns false so no pulses flow.
        datasette.MotorEnabled = true;
        datasette.PlayPressed = true;

        machine.Clock.Step(10_000);

        var icr = cia1.Read(0xDC0D);
        (icr & 0x10).Should().Be(0x00,
            "without a tape, no pulses are produced so CIA1 FLAG never latches");
    }
}

public void Tap_Attach_And_Datasette_ReadPulse_Requires_Motor_And_Play()
{
    var tap = CreateTapImage(1, [10, 0, 0x40, 0x1F, 0x00]);

    Assert.True(TapImage.TryAttach(tap, out var image));

    var datasette = new Datasette();
    Assert.True(datasette.Attach(image!));
    Assert.True(datasette.HasTape);

    Assert.False(datasette.TryReadNextPulse(out _));

    datasette.MotorEnabled = true;
    datasette.PlayPressed = true;

    Assert.True(datasette.TryReadNextPulse(out var shortPulse));
    Assert.Equal(80, shortPulse);

    Assert.True(datasette.TryReadNextPulse(out var overflowPulse));
    Assert.Equal(8000, overflowPulse);

    Assert.False(datasette.TryReadNextPulse(out _));
}

